<?php
echo '<style>main form[method=post],main form[method="post"]{display:none!important}</style>';
echo '<div class="notice">Research archive — previous records are retained for reference. <a href="/desks/rd/index.php">Open Research Tracking</a> for new work. Changes in this archive are disabled.</div>';

if(!researchAccess($user)){echo '<div class="notice error">Research access requires a registered student, supervisor or coordinator account.</div>';return;}
if(!researchReady()){echo '<div class="notice">Run the Research and Library migration first.</div>';return;}
function researchForm(string $action,int $id=0,int $revision=0):void{echo '<form method="post">';csrf();echo '<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="revision" value="'.$revision.'">';}
function researchInput(string $name,string $label,string $type='text',string $value=''):void{echo '<label>'.e($label);$value=($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST[$name])&&is_string($_POST[$name]))?$_POST[$name]:$value;if($type==='textarea')echo '<textarea rows="4" name="'.e($name).'" required>'.e($value).'</textarea>';else echo '<input name="'.e($name).'" type="'.e($type).'" value="'.e($value).'" required>';echo '</label>';}
require_once __DIR__.'/workspace.php';
$manager=researchManager($user);$student=researchStudent($user);$id=(int)($_GET['id']??0);
?>
<link rel="stylesheet" href="assets/research-workflow.css?v=1">
<?php if(rwReady()&&!$id)rwDashboard($user);?>
<div class="heading" <?=rwReady()&&!$id?'hidden':''?>><div><span class="eyebrow">RESEARCH TRACK</span><h1>Research Management</h1><p>Proposals, supervision, progress and research outputs.</p></div><a class="button secondary" href="?page=research">All projects</a></div>
<?php if($id):try{$r=researchGet($user,$id);}catch(Throwable $e){echo '<div class="notice error">'.e($e->getMessage()).'</div>';return;}$period=one('SELECT * FROM research_periods WHERE id=?',[$r['period_id']]);$owner=(int)$r['student_id']===(int)$user['id'];$supervisor=(int)$r['supervisor_id']===(int)$user['id'];$person=one('SELECT u.name,u.email,s.student_number,s.programme FROM users u LEFT JOIN research_students s ON s.user_id=u.id WHERE u.id=?',[$r['student_id']]);$teacher=one('SELECT name FROM users WHERE id=?',[$r['supervisor_id']]);?>
<section class="card research-project"><span class="badge"><?=e($r['status'])?></span><h2><?=e($r['title'])?></h2><p><?=e($person['name'].' · '.($person['student_number']??'').' · '.$r['department'])?><br><?=e(($person['programme']??'').' · '.$person['email'])?><br>Supervisor: <?=e($teacher['name'])?> · Project deadline: <?=e($period['due_on'])?><br>Funding: Nu. <?=number_format((float)$r['funding'],2)?></p><dl class="details"><?php foreach(['objectives'=>'Working topic statement','methodology'=>'Methodology','team'=>'Research team','outcomes'=>'Expected outcomes']as $k=>$label):if(trim($r[$k])==='')continue;?><div><dt><?=e($label)?></dt><dd><?=nl2br(e($r[$k]))?></dd></div><?php endforeach;?></dl></section>
<?php if(rwReady()){rwProjectWorkspace($user,$r);if(!$owner&&!$supervisor&&!$manager&&!rwPL($user,$r))return;}?>
<?php if(($supervisor||$manager)&&in_array($r['status'],['Submitted','Approved'],true)):?><section class="card"><h2>Review / decision</h2><?php researchForm('research_decision',$id,(int)$r['revision']);field('status','Decision','select',$r['status']==='Approved'?['Completed']:['Approved','Changes requested','Rejected']);researchInput('details','Review comments','textarea');?><button>Save decision and notify student</button></form></section><?php endif;?>
<?php if($manager):?><section class="card" id="delete-project"><details><summary>Delete project</summary><p>Remove this project from the project list and reports. Its history and a deletion audit record are retained. The student can submit again while registration is open.</p><?php researchForm('research_delete',$id,(int)$r['revision']);researchInput('reason','Reason for deletion','textarea');?><label><input type="checkbox" name="confirmed" value="1" required> I confirm deletion of this project.</label><button class="danger">Delete project</button></form></details></section><?php endif;?>
<section class="card"><h2>Add progress or comment</h2><?php researchForm('research_update',$id,(int)$r['revision']);?><div class="form-grid"><?php field('kind','Update type','select',$owner&&$r['status']==='Approved'?['Progress','Milestone','Activity','Expenditure','Challenge','Journal article','Conference paper','Report','Dataset','Patent','Other output','Comment']:['Comment']);field('amount','Expenditure amount (Nu.; for expenditure only)','number',[],false);field('link','Output link (optional)','url',[],false);researchInput('details','Details / comments','textarea');?></div><button>Save and notify</button></form></section>
<section class="card"><h2>Project history</h2><?php foreach(all('SELECT x.*,u.name FROM research_updates x JOIN users u ON u.id=x.actor_id WHERE project_id=? ORDER BY x.id DESC',[$id])as $update):?><article class="activity"><b><?=e($update['kind'])?></b> · <?=e($update['name'])?><small><?=e($update['created_at'])?></small><?php if($update['kind']==='Proposal submitted'):$snapshot=json_decode($update['details'],true);?><details><summary>Proposal version</summary><?php foreach(['title','objectives','methodology','team','outcomes']as $k):?><p><b><?=e(ucfirst($k))?>:</b> <?=nl2br(e($snapshot[$k]??''))?></p><?php endforeach;?></details><?php else:?><p><?=nl2br(e($update['details']))?></p><?php endif;?><?php if($update['kind']==='Expenditure'):?><p>Nu. <?=number_format((float)$update['amount'],2)?></p><?php endif;if($update['link']):?><a href="<?=e($update['link'])?>" rel="noopener noreferrer" target="_blank">View research output</a><?php endif;?></article><?php endforeach;?></section>
<?php endif;?>
<?php if($student&&(!$id||($owner&&$r['status']==='Changes requested'))):$form=$id?$r:[];$periods=all('SELECT * FROM research_periods WHERE department=? AND active=1 AND opens_on<=? AND closes_on>=? ORDER BY id DESC',[$user['department'],date('Y-m-d'),date('Y-m-d')]);?><section class="card"><h2><?=$id?'Resubmit returned proposal':'Register a research proposal'?></h2><?php if(!$periods):?><p>Proposal registration is currently closed. DAA will announce the next period.</p><?php else:researchForm('research_submit',$id,(int)($form['revision']??0));?><div class="form-grid"><label>Registration period<select name="period_id" required><?php foreach($periods as $p):if($id&&(int)$p['id']!==(int)$r['period_id'])continue;?><option value="<?=$p['id']?>"><?=e($p['title'].' · Registration until '.$p['closes_on'].' · Project due '.$p['due_on'])?></option><?php endforeach;?></select></label><label>Supervisor<select name="supervisor_id" required><option value="">Select teaching staff…</option><?php foreach(all("SELECT id,name FROM users WHERE active=1 AND department=? AND role IN ('faculty','hod','pl','daa') ORDER BY name",[$user['department']])as $s):?><option value="<?=$s['id']?>" <?=(int)($form['supervisor_id']??0)===(int)$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></label><?php researchInput('title','Research title','text',$form['title']??'');researchInput('objectives','Working topic statement — short scope and focus','textarea',$form['objectives']??'');echo '<input type="hidden" name="funding" value="0"><input type="hidden" name="methodology" value="To be developed in proposal"><input type="hidden" name="team" value="Individual research"><input type="hidden" name="outcomes" value="To be developed in proposal">';?></div><button>Submit proposal and notify supervisor / DAA</button></form><?php endif;?></section><?php endif;?>
<?php if(!$id):
$where=$manager?'1=1':($user['role']==='pl'?'p.department=?':'(p.student_id=? OR p.supervisor_id=?)');$args=$manager?[]:($user['role']==='pl'?[$user['department']]:[$user['id'],$user['id']]);$dept=trim($_GET['department']??'');$state=trim($_GET['status']??'');if($dept!==''){$where.=' AND p.department=?';$args[]=$dept;}if($state!==''){$where.=' AND p.status=?';$args[]=$state;}
$projects=all('SELECT p.*,s.name AS student_name,t.name AS supervisor_name FROM research_projects p JOIN users s ON s.id=p.student_id JOIN users t ON t.id=p.supervisor_id WHERE '.$where.' ORDER BY p.id DESC',$args);$total=count($projects);$pageNo=max(1,min(max(1,(int)ceil($total/10)),(int)($_GET['p']??1)));
?><section class="card" <?=rwReady()?'hidden':''?>><h2>Projects and reporting</h2><form method="get" class="form-grid"><input type="hidden" name="page" value="research"><?php field('department','Department','select',departments(),false);field('status','Status','select',['Submitted','Changes requested','Approved','Rejected','Completed'],false);?><button>Filter projects</button></form><div class="stats"><div><small>Projects matching filters</small><strong><?=$total?></strong></div><div><small>Active / approved</small><strong><?=count(array_filter($projects,fn($r)=>$r['status']==='Approved'))?></strong></div><div><small>Completed</small><strong><?=count(array_filter($projects,fn($r)=>$r['status']==='Completed'))?></strong></div><div><small>Funding (Nu.)</small><strong><?=number_format(array_sum(array_column($projects,'funding')),2)?></strong></div></div><div class="table-wrap"><table class="ac-bordered"><thead><tr><th>No.</th><th>Project / department</th><th>Student</th><th>Supervisor</th><th>Status</th><th>Expenditure / outputs</th><?php if($manager):?><th>Actions</th><?php endif;?></tr></thead><tbody><?php foreach(array_slice($projects,($pageNo-1)*10,10)as $i=>$p):$sum=one("SELECT SUM(amount) AS spent,SUM(CASE WHEN kind IN ('Journal article','Conference paper','Report','Dataset','Patent','Other output') THEN 1 ELSE 0 END) AS outputs FROM research_updates WHERE project_id=?",[$p['id']]);?><tr><td><?=($pageNo-1)*10+$i+1?></td><td><a href="?page=research&id=<?=$p['id']?>"><?=e($p['title'])?></a><small><?=e($p['department'])?></small></td><td><?=e($p['student_name'])?></td><td><?=e($p['supervisor_name'])?></td><td><?=e($p['status'])?></td><td>Nu. <?=number_format((float)$sum['spent'],2)?><small><?=(int)$sum['outputs']?> outputs</small></td><?php if($manager):?><td><a class="button secondary" href="?page=research&amp;id=<?=$p['id']?>#delete-project">Delete project</a></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><div class="pagination"><span>Page <?=$pageNo?> of <?=max(1,(int)ceil($total/10))?></span><?php foreach(['Previous'=>$pageNo-1,'Next'=>$pageNo+1]as $label=>$n)if($n>=1&&$n<=ceil($total/10)):?><a class="button secondary" href="?<?=e(http_build_query(['page'=>'research','p'=>$n,'department'=>$dept,'status'=>$state]))?>"><?=$label?></a><?php endif;?></div></section>
<?php if($manager):?><section class="card"><details><summary>Recent project deletions</summary><?php foreach(all("SELECT x.*,u.name FROM research_updates x JOIN users u ON u.id=x.actor_id WHERE x.kind='Project deleted' ORDER BY x.id DESC LIMIT 20")as $deleted):$snapshot=json_decode($deleted['details'],true);?><article class="activity"><b><?=e($snapshot['project']['title']??'Project')?></b><p><?=e($deleted['name'].' · '.$deleted['created_at'])?></p><p><?=e($snapshot['reason']??'')?></p></article><?php endforeach;?></details></section><?php endif;?>
<?php if($manager):?><section class="card"><h2>DAA registration periods and timelines</h2><?php researchForm('research_period');?><div class="form-grid"><?php researchInput('title','Period title (e.g. Final-year research 2027)');field('department','Department','select',departments());researchInput('opens_on','Registration opens','date');researchInput('closes_on','Registration closes','date');researchInput('due_on','Project completion deadline','date');?></div><button>Create period</button></form><?php foreach(all('SELECT * FROM research_periods ORDER BY id DESC')as $p):?><div class="activity"><b><?=e($p['title'])?></b><p><?=e($p['department'].' · '.$p['opens_on'].' to '.$p['closes_on'].' · Project due '.$p['due_on'])?></p><?php researchForm('research_period_toggle');?><input type="hidden" name="period_id" value="<?=$p['id']?>"><button class="secondary"><?=$p['active']?'Close registration':'Enable registration'?></button></form><details><summary>Edit timeline</summary><?php researchForm('research_period');?><input type="hidden" name="period_id" value="<?=$p['id']?>"><input type="hidden" name="department" value="<?=e($p['department'])?>"><div class="form-grid"><?php researchInput('title','Period title','text',$p['title']);researchInput('opens_on','Registration opens','date',$p['opens_on']);researchInput('closes_on','Registration closes','date',$p['closes_on']);researchInput('due_on','Project completion deadline','date',$p['due_on']);?></div><button>Save timeline</button></form></details></div><?php endforeach;?></section><?php endif;?>
<?php if($user['role']==='admin'):?><section class="card"><h2>Register / update student account</h2><p>Use the student's own email. A password setup link is queued to their mailbox. Existing consultation-only student contacts gain research access only after registration here.</p><?php researchForm('research_student');?><div class="form-grid"><?php field('name','Student name');field('email','Student email','email');field('student_number','Student number');field('department','Department','select',departments());field('programme','Programme','select',programmes());?></div><button>Register student and email password link</button></form><h3>Registered students</h3><?php foreach(all('SELECT s.*,u.name,u.active,u.email FROM research_students s JOIN users u ON u.id=s.user_id ORDER BY u.name')as $s):?><div class="activity"><?=e($s['name'].' · '.$s['student_number'].' · '.$s['email'])?><?php researchForm('research_student_status');?><input type="hidden" name="student_id" value="<?=$s['user_id']?>"><input type="hidden" name="active" value="<?=$s['active']?'0':'1'?>"><button class="secondary"><?=$s['active']?'Disable':'Enable'?></button></form></div><?php endforeach;?></section><?php endif;endif;?>
